export class Ambience{
 constructor(){this.enabled=false;this.ctx=null;this.timer=null;this.beat=0;}
 async toggle(){this.enabled=!this.enabled;if(this.enabled){try{if(!this.ctx){this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=.22;this.master.connect(this.ctx.destination)}await this.ctx.resume();this.timer=setInterval(()=>this.tick(),430);this.tick()}catch{this.enabled=false}}else{clearInterval(this.timer);if(this.ctx)await this.ctx.suspend()}return this.enabled}
 tick(){if(!this.enabled||document.hidden)return;const c=this.ctx,t=c.currentTime;const beat=this.beat++;
 const bass=c.createOscillator(),g=c.createGain();bass.type='sine';bass.frequency.setValueAtTime([65.41,77.78,58.27,87.31][Math.floor(beat/8)%4],t);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.18,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.6);bass.connect(g).connect(this.master);bass.start(t);bass.stop(t+.7);
 if(beat%2===1){const len=Math.floor(c.sampleRate*.13),buf=c.createBuffer(1,len,c.sampleRate),arr=buf.getChannelData(0);for(let i=0;i<len;i++)arr[i]=(Math.random()*2-1)*Math.exp(-i/len*8);const s=c.createBufferSource(),filter=c.createBiquadFilter(),gg=c.createGain();s.buffer=buf;filter.type='highpass';filter.frequency.value=1900;gg.gain.value=.065;s.connect(filter).connect(gg).connect(this.master);s.start(t)}
 if(beat%8===0){const o=c.createOscillator(),gain=c.createGain();o.type='triangle';o.frequency.value=[261.63,311.13,233.08,349.23][Math.floor(beat/8)%4];gain.gain.setValueAtTime(.001,t);gain.gain.exponentialRampToValueAtTime(.045,t+.4);gain.gain.exponentialRampToValueAtTime(.001,t+3);o.connect(gain).connect(this.master);o.start(t);o.stop(t+3.1)}}
 chime(){if(!this.enabled||!this.ctx)return;const t=this.ctx.currentTime;[523.25,659.25,783.99].forEach((f,i)=>{const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.frequency.value=f;g.gain.setValueAtTime(.001,t+i*.1);g.gain.exponentialRampToValueAtTime(.14,t+i*.1+.02);g.gain.exponentialRampToValueAtTime(.001,t+i*.1+1);o.connect(g).connect(this.master);o.start(t+i*.1);o.stop(t+i*.1+1)})}
}
